#include "kernel_operator.h"
#include <cstdint>

// Specialized contract:
// x: [128,4096,4095] float32 contiguous, reduce dim=1 => y: [128,4095] int64 indices
//
// Optimization: block-level tiling over inner dimension to increase parallelism,
// plus reduction unroll and direct __gm__ pointer loads to reduce scalar/control overhead.

class KernelArgmaxOverADimensionCustom {
public:
    __aicore__ inline KernelArgmaxOverADimensionCustom() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                               uint32_t batch, uint32_t reduceDim, uint32_t innerDim,
                               uint32_t tileInner, uint32_t tilesPerBatch)
    {
        batch_ = batch;
        reduceDim_ = reduceDim;
        innerDim_ = innerDim;
        tileInner_ = tileInner;
        tilesPerBatch_ = tilesPerBatch;

        xGm_.SetGlobalBuffer((__gm__ float*)x);
        yGm_.SetGlobalBuffer((__gm__ int64_t*)y);

        pipe_.InitBuffer(inputQueue_, 1, tileInner_ * sizeof(float));
        pipe_.InitBuffer(outputQueue_, 1, tileInner_ * sizeof(int64_t));
        pipe_.InitBuffer(maxBuf_, tileInner_ * sizeof(float));
        pipe_.InitBuffer(indexBuf_, tileInner_ * sizeof(float));
        pipe_.InitBuffer(rowIndexBuf_, tileInner_ * sizeof(float));
        pipe_.InitBuffer(maskBuf_, tileInner_ * sizeof(uint8_t));
    }

    __aicore__ inline void Process()
    {
        if (batch_ == 0 || reduceDim_ == 0 || innerDim_ == 0 || tileInner_ == 0 || tilesPerBatch_ == 0) {
            return;
        }

        const uint32_t blockIdx = (uint32_t)AscendC::GetBlockIdx();
        const uint32_t b = blockIdx / tilesPerBatch_;
        const uint32_t tileId = blockIdx - b * tilesPerBatch_;
        if (b >= batch_) {
            return;
        }

        const uint32_t i0 = tileId * tileInner_;
        if (i0 >= innerDim_) {
            return;
        }

        uint32_t tileLen = tileInner_;
        if (i0 + tileLen > innerDim_) {
            tileLen = innerDim_ - i0;
        }

        const uint64_t batchBase = (uint64_t)b * (uint64_t)reduceDim_ * (uint64_t)innerDim_;
        const uint32_t K = reduceDim_;
        const uint32_t I = innerDim_;

        auto maxValue = maxBuf_.Get<float>();
        auto maxIndex = indexBuf_.Get<float>();
        auto rowIndex = rowIndexBuf_.Get<float>();
        auto updateMask = maskBuf_.Get<uint8_t>();

        AscendC::Duplicate(maxValue, -3.402823466e+38f, tileInner_);
        AscendC::Duplicate(maxIndex, 0.0f, tileInner_);
        AscendC::Duplicate(rowIndex, 0.0f, tileInner_);

        // A reduction row is contiguous across innerDim.  Update 64 output
        // positions together and retain the old index on equality.
        for (uint32_t r = 0; r < K; ++r) {
            auto input = inputQueue_.AllocTensor<float>();
            const uint64_t rowOffset = batchBase + (uint64_t)r * (uint64_t)I + (uint64_t)i0;
            AscendC::DataCopyExtParams copyParams(1, tileLen * sizeof(float), 0, 0, 0);
            AscendC::DataCopyPadExtParams<float> padParams(
                true, 0, 0, -3.402823466e+38f);
            AscendC::DataCopyPad(input, xGm_[rowOffset], copyParams, padParams);
            inputQueue_.EnQue(input);
            input = inputQueue_.DeQue<float>();

            AscendC::Compare(updateMask, input, maxValue, AscendC::CMPMODE::GT, tileInner_);
            AscendC::Select(maxIndex, updateMask, rowIndex, maxIndex,
                            AscendC::SELMODE::VSEL_TENSOR_TENSOR_MODE, tileInner_);
            AscendC::Max(maxValue, maxValue, input, tileInner_);
            AscendC::Adds(rowIndex, rowIndex, 1.0f, tileInner_);
            inputQueue_.FreeTensor(input);
        }

        AscendC::PipeBarrier<PIPE_ALL>();
        auto output = outputQueue_.AllocTensor<int64_t>();
        for (uint32_t j = 0; j < tileLen; ++j) {
            output.SetValue(j, (int64_t)maxIndex.GetValue(j));
        }
        outputQueue_.EnQue(output);
        output = outputQueue_.DeQue<int64_t>();
        const uint64_t outOffset = (uint64_t)b * (uint64_t)innerDim_ + (uint64_t)i0;
        AscendC::DataCopyExtParams outParams(1, tileLen * sizeof(int64_t), 0, 0, 0);
        AscendC::DataCopyPad(yGm_[outOffset], output, outParams);
        outputQueue_.FreeTensor(output);
    }

private:
    AscendC::GlobalTensor<float> xGm_;
    AscendC::GlobalTensor<int64_t> yGm_;
    uint32_t batch_{0};
    uint32_t reduceDim_{0};
    uint32_t innerDim_{0};
    uint32_t tileInner_{0};
    uint32_t tilesPerBatch_{0};
    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> inputQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outputQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maxBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> indexBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> rowIndexBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maskBuf_;
};

extern "C" __global__ __aicore__ void argmax_over_a_dimension_custom(
    GM_ADDR x, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);
    KernelArgmaxOverADimensionCustom op;
    op.Init(x, y,
            tiling_data.batch, tiling_data.reduceDim, tiling_data.innerDim,
            tiling_data.tileInner, tiling_data.tilesPerBatch);
    op.Process();
}

