#include "kernel_operator.h"
#include <cstdint>

// Specialized contract:
// x: [128,4096,4095] float32 contiguous, reduce dim=1 => y: [128,4095] int64 indices

class KernelArgminOverADimensionCustom {
public:
    __aicore__ inline KernelArgminOverADimensionCustom() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                               uint32_t /*totalX*/, uint32_t /*totalY*/,
                               uint32_t batch, uint32_t reduceDim, uint32_t innerDim,
                               uint32_t /*unrollR*/)
    {
        batch_ = batch;
        reduceDim_ = reduceDim;
        innerDim_ = innerDim;
        xGm_.SetGlobalBuffer((__gm__ float*)x);
        yGm_.SetGlobalBuffer((__gm__ int64_t*)y);

        pipe_.InitBuffer(inputQueue_, 1, TILE_INNER * sizeof(float));
        pipe_.InitBuffer(outputQueue_, 1, TILE_INNER * sizeof(int64_t));
        pipe_.InitBuffer(minBuf_, TILE_INNER * sizeof(float));
        pipe_.InitBuffer(indexBuf_, TILE_INNER * sizeof(float));
        pipe_.InitBuffer(rowIndexBuf_, TILE_INNER * sizeof(float));
        pipe_.InitBuffer(maskBuf_, TILE_INNER * sizeof(uint8_t));
    }

    __aicore__ inline void Process()
    {
        if (batch_ == 0 || reduceDim_ == 0 || innerDim_ == 0) return;

        const uint32_t blockNum = (uint32_t)AscendC::GetBlockNum();
        const uint32_t blockIdx = (uint32_t)AscendC::GetBlockIdx();
        if (blockNum == 0) return;

        const uint32_t tilesPerBatch = (innerDim_ + TILE_INNER - 1) / TILE_INNER;
        const uint32_t totalTiles = batch_ * tilesPerBatch;
        for (uint32_t task = blockIdx; task < totalTiles; task += blockNum) {
            const uint32_t b = task / tilesPerBatch;
            const uint32_t tileId = task - b * tilesPerBatch;
            const uint32_t i0 = tileId * TILE_INNER;
            uint32_t tileLen = TILE_INNER;
            if (i0 + tileLen > innerDim_) tileLen = innerDim_ - i0;

            const uint64_t batchBase = (uint64_t)b * (uint64_t)reduceDim_ * (uint64_t)innerDim_;
            auto minValue = minBuf_.Get<float>();
            auto minIndex = indexBuf_.Get<float>();
            auto rowIndex = rowIndexBuf_.Get<float>();
            auto updateMask = maskBuf_.Get<uint8_t>();

            AscendC::Duplicate(minValue, 3.402823466e+38f, TILE_INNER);
            AscendC::Duplicate(minIndex, 0.0f, TILE_INNER);
            AscendC::Duplicate(rowIndex, 0.0f, TILE_INNER);

            for (uint32_t r = 0; r < reduceDim_; ++r) {
                auto input = inputQueue_.AllocTensor<float>();
                const uint64_t rowOffset = batchBase + (uint64_t)r * (uint64_t)innerDim_ + (uint64_t)i0;
                AscendC::DataCopyExtParams copyParams(1, tileLen * sizeof(float), 0, 0, 0);
                AscendC::DataCopyPadExtParams<float> padParams(true, 0, 0, 3.402823466e+38f);
                AscendC::DataCopyPad(input, xGm_[rowOffset], copyParams, padParams);
                inputQueue_.EnQue(input);
                input = inputQueue_.DeQue<float>();

                AscendC::Compare(updateMask, input, minValue, AscendC::CMPMODE::LT, TILE_INNER);
                AscendC::Select(minIndex, updateMask, rowIndex, minIndex,
                                AscendC::SELMODE::VSEL_TENSOR_TENSOR_MODE, TILE_INNER);
                AscendC::Min(minValue, minValue, input, TILE_INNER);
                AscendC::Adds(rowIndex, rowIndex, 1.0f, TILE_INNER);
                inputQueue_.FreeTensor(input);
            }

            AscendC::PipeBarrier<PIPE_ALL>();
            auto output = outputQueue_.AllocTensor<int64_t>();
            for (uint32_t j = 0; j < tileLen; ++j) {
                output.SetValue(j, (int64_t)minIndex.GetValue(j));
            }
            outputQueue_.EnQue(output);
            output = outputQueue_.DeQue<int64_t>();
            const uint64_t outOffset = (uint64_t)b * (uint64_t)innerDim_ + (uint64_t)i0;
            AscendC::DataCopyExtParams outParams(1, tileLen * sizeof(int64_t), 0, 0, 0);
            AscendC::DataCopyPad(yGm_[outOffset], output, outParams);
            outputQueue_.FreeTensor(output);
        }
    }

private:
    static constexpr uint32_t TILE_INNER = 64;
    AscendC::GlobalTensor<float> xGm_;
    AscendC::GlobalTensor<int64_t> yGm_;
    uint32_t batch_{0};
    uint32_t reduceDim_{0};
    uint32_t innerDim_{0};
    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> inputQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outputQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> minBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> indexBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> rowIndexBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maskBuf_;
};

extern "C" __global__ __aicore__ void argmin_over_a_dimension_custom(
    GM_ADDR x, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);
    KernelArgminOverADimensionCustom op;
    op.Init(x, y,
            tiling_data.totalX, tiling_data.totalY,
            tiling_data.batch, tiling_data.reduceDim, tiling_data.innerDim,
            tiling_data.unrollR);
    op.Process();
}

