#include "kernel_operator.h"

// Fixed specialization (benchmark contract):
// x: [16, 3, 64, 64, 64] float32 (NCDHW)
// w: [64, 3, 3, 3, 3] float32
// y: [16, 64, 62, 62, 62] float32
// stride=1, pad=0, dilation=1, groups=1, bias=false
//
// This round:
// - Pass blockDim via tiling to avoid GetBlockNum() overhead and improve determinism.
// - Increase launch parallelism (host) to reduce pipeline gaps.
// - Keep weight-per-oc caching and ow tiling (TOW=4).

class KernelConvStandard3dSquare {
public:
    __aicore__ inline KernelConvStandard3dSquare() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR w, GM_ADDR y, uint32_t blockDim)
    {
        xGm.SetGlobalBuffer((__gm__ float*)x);
        wGm.SetGlobalBuffer((__gm__ float*)w);
        yGm.SetGlobalBuffer((__gm__ float*)y);
        blockDim_ = blockDim;
        pipe_.InitBuffer(inputQueue_, 1, INPUT_VALUES * sizeof(float));
        pipe_.InitBuffer(outputQueue_, 1, OUTPUT_VALUES * sizeof(float));
        pipe_.InitBuffer(tmpBuf_, OUTPUT_VALUES * sizeof(float));
        pipe_.InitBuffer(shiftBuf_, OUTPUT_VALUES * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        constexpr int N = 16;
        constexpr int CIN = 3;
        constexpr int D = 64;
        constexpr int H = 64;
        constexpr int W = 64;

        constexpr int COUT = 64;
        constexpr int DO = 62;
        constexpr int HO = 62;
        constexpr int WO = 62;

        constexpr int K = 3;
        constexpr int TOW = 4;

        constexpr int64_t HW = (int64_t)H * W;
        constexpr int64_t DHW = (int64_t)D * H * W;

        // Rows are (n, oc, od, oh)
        constexpr int64_t ROWS = (int64_t)N * COUT * DO * HO;

        const uint32_t bid = (uint32_t)AscendC::GetBlockIdx();
        uint32_t bdim = blockDim_;
        if (bdim == 0) { bdim = 1; }

        const int64_t chunk = (ROWS + (int64_t)bdim - 1) / (int64_t)bdim;
        int64_t rowStart = (int64_t)bid * chunk;
        int64_t rowEnd = rowStart + chunk;
        if (rowEnd > ROWS) rowEnd = ROWS;

        for (int64_t row = rowStart; row < rowEnd; ++row) {
            int64_t t = row;
            int oh = (int)(t % HO); t /= HO;
            int od = (int)(t % DO); t /= DO;
            int oc = (int)(t % COUT); t /= COUT;
            int n  = (int)t;

            const int64_t yRowBase = (((((int64_t)n * COUT + oc) * DO + od) * HO + oh) * WO);

            const int id0 = od;
            const int ih0 = oh;

            const int64_t xNBase = (int64_t)n * (int64_t)CIN * DHW;

            int64_t pBase[27];
#pragma unroll
            for (int ic = 0; ic < CIN; ++ic) {
                const int64_t xNcBase = xNBase + (int64_t)ic * DHW;
#pragma unroll
                for (int kz = 0; kz < 3; ++kz) {
                    const int64_t xZBase = xNcBase + (int64_t)(id0 + kz) * HW;
#pragma unroll
                    for (int ky = 0; ky < 3; ++ky) {
                        const int p = ic * 9 + kz * 3 + ky;
                        pBase[p] = xZBase + (int64_t)(ih0 + ky) * W;
                    }
                }
            }

            float w0[27], w1[27], w2[27];
            const int64_t wBase = (int64_t)oc * (CIN * K * K * K);
#pragma unroll
            for (int p = 0; p < 27; ++p) {
                const int64_t wb = wBase + (int64_t)p * 3;
                w0[p] = wGm.GetValue((int)(wb + 0));
                w1[p] = wGm.GetValue((int)(wb + 1));
                w2[p] = wGm.GetValue((int)(wb + 2));
            }

            AscendC::LocalTensor<float> outputLocal = outputQueue_.AllocTensor<float>();
            AscendC::LocalTensor<float> tmpLocal = tmpBuf_.Get<float>();
            AscendC::LocalTensor<float> shiftLocal = shiftBuf_.Get<float>();
            bool firstTap = true;
#pragma unroll
            for (int p = 0; p < 27; ++p) {
                AscendC::LocalTensor<float> inputLocal = inputQueue_.AllocTensor<float>();
                AscendC::DataCopy(inputLocal, xGm[pBase[p]], W);
                inputQueue_.EnQue(inputLocal);
                inputLocal = inputQueue_.DeQue<float>();
                for (uint32_t pad = W; pad < INPUT_VALUES; ++pad) {
                    inputLocal.SetValue(pad, 0.0f);
                }
#pragma unroll
                for (int kx = 0; kx < 3; ++kx) {
                    for (uint32_t lane = 0; lane < OUTPUT_VALUES; ++lane) {
                        shiftLocal.SetValue(lane, inputLocal.GetValue((uint32_t)kx + lane));
                    }
                    const float ww = (kx == 0) ? w0[p] : ((kx == 1) ? w1[p] : w2[p]);
                    if (firstTap) {
                        AscendC::Muls(outputLocal, shiftLocal, ww, OUTPUT_VALUES);
                        firstTap = false;
                    } else {
                        AscendC::Muls(tmpLocal, shiftLocal, ww, OUTPUT_VALUES);
                        AscendC::Add(outputLocal, outputLocal, tmpLocal, OUTPUT_VALUES);
                    }
                }
                inputQueue_.FreeTensor(inputLocal);
            }
            outputQueue_.EnQue(outputLocal);
            outputLocal = outputQueue_.DeQue<float>();
            AscendC::DataCopyExtParams outputCopy{1, WO * sizeof(float), 0, 0, 0};
            AscendC::DataCopyPad(yGm[yRowBase], outputLocal, outputCopy);
            outputQueue_.FreeTensor(outputLocal);
        }
    }

private:
    static constexpr uint32_t INPUT_VALUES = 72;
    static constexpr uint32_t OUTPUT_VALUES = 64;
    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> wGm;
    AscendC::GlobalTensor<float> yGm;
    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> inputQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outputQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> shiftBuf_;
    uint32_t blockDim_{1};
};

