                                const float wv2 = wGm.GetValue(wBaseKh + 2), wv3 = wGm.GetValue(wBaseKh + 3);
                                const float wv4 = wGm.GetValue(wBaseKh + 4), wv5 = wGm.GetValue(wBaseKh + 5);
                                const float wv6 = wGm.GetValue(wBaseKh + 6);
#define ACC_BORDER(ACC, OFFSET) \
                                do { \
                                    int iw = (ow + (OFFSET)); \
                                    if ((uint32_t)iw < (uint32_t)WIN) (ACC) += xGm.GetValue(xBaseH + (int64_t)iw) * wv0; \
                                    iw -= 1; if ((uint32_t)iw < (uint32_t)WIN) (ACC) += xGm.GetValue(xBaseH + (int64_t)iw) * wv1; \
                                    iw -= 1; if ((uint32_t)iw < (uint32_t)WIN) (ACC) += xGm.GetValue(xBaseH + (int64_t)iw) * wv2; \
                                    iw -= 1; if ((uint32_t)iw < (uint32_t)WIN) (ACC) += xGm.GetValue(xBaseH + (int64_t)iw) * wv3; \
                                    iw -= 1; if ((uint32_t)iw < (uint32_t)WIN) (ACC) += xGm.GetValue(xBaseH + (int64_t)iw) * wv4; \
                                    iw -= 1; if ((uint32_t)iw < (uint32_t)WIN) (ACC) += xGm.GetValue(xBaseH + (int64_t)iw) * wv5; \
                                    iw -= 1; if ((uint32_t)iw < (uint32_t)WIN) (ACC) += xGm.GetValue(xBaseH + (int64_t)iw) * wv6; \
                                } while (0)
                                if (tile >= 1) ACC_BORDER(acc0, 0);
                                if (tile >= 2) ACC_BORDER(acc1, 1);
                                if (tile >= 3) ACC_BORDER(acc2, 2);
                                if (tile >= 4) ACC_BORDER(acc3, 3);
                                if (tile >= 5) ACC_BORDER(acc4, 4);
                                if (tile >= 6) ACC_BORDER(acc5, 5);
                                if (tile >= 7) ACC_BORDER(acc6, 6);
                                if (tile >= 8) ACC_BORDER(acc7, 7);
