#include "matmul_for_upper_triangular_matrices_custom_tiling.h"
#include "register/op_def_registry.h"
#include "tiling/platform/platform_ascendc.h"
#include "tiling/tiling_api.h"

using namespace matmul_tiling;

namespace optiling {

static ge::graphStatus TilingFunc(gert::TilingContext *context)
{
    auto ascendcPlatform = platform_ascendc::PlatformAscendC(context->GetPlatformInfo());

    auto shape_a = context->GetInputTensor(0)->GetOriginShape();
    auto shape_b = context->GetInputTensor(1)->GetOriginShape();
    if (shape_a.GetDimNum() != 2 || shape_b.GetDimNum() != 2) {
        return ge::GRAPH_FAILED;
    }

    const int32_t M = static_cast<int32_t>(shape_a.GetDim(0));
    const int32_t K = static_cast<int32_t>(shape_a.GetDim(1));
    const int32_t K2 = static_cast<int32_t>(shape_b.GetDim(0));
    const int32_t N = static_cast<int32_t>(shape_b.GetDim(1));
    if (M <= 0 || N <= 0 || K <= 0 || K != K2) {
        return ge::GRAPH_FAILED;
    }

    // Larger base tile to reduce per-tile overhead; tiler will legalize.
    const int32_t baseM = 128;
    const int32_t baseN = 128;

    MultiCoreMatmulTiling cubeTiling(ascendcPlatform);
    cubeTiling.SetDim(2);

    cubeTiling.SetAType(TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT, /*transpose=*/false);
    cubeTiling.SetBType(TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT, /*transpose=*/false);
    cubeTiling.SetCType(TPosition::GM, CubeFormat::ND, matmul_tiling::DataType::DT_FLOAT);

    cubeTiling.SetShape(M, N, K);
    cubeTiling.SetOrgShape(M, N, K);

    cubeTiling.SetFixSplit(baseM, baseN, -1);
    cubeTiling.SetBias(false);
    cubeTiling.SetBufferSpace(-1, -1, -1);

    MatmulForUpperTriangularMatricesCustomTilingData tiling;
    if (cubeTiling.GetTiling(tiling.cubeTilingData) == -1) {
        return ge::GRAPH_FAILED;
    }

    // Use matmul tiler's intended parallelism; clamp to AIC core count.
    int32_t used = static_cast<int32_t>(tiling.cubeTilingData.get_usedCoreNum());
    int32_t maxCore = static_cast<int32_t>(ascendcPlatform.GetCoreNumAic());
    if (maxCore <= 0) maxCore = 1;
    if (used <= 0) used = 1;
    if (used > maxCore) used = maxCore;
    context->SetBlockDim(static_cast<uint32_t>(used));

    // Keep tiling-key pattern for tmp UB workspace quirk on some SoCs.
    if (ascendcPlatform.GetSocVersion() == platform_ascendc::SocVersion::ASCEND310P) {
        context->SetTilingKey(2);
    } else {
        context->SetTilingKey(1);
    }

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(),
                        context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t userWorkspaceSize = 0;
    size_t systemWorkspaceSize = static_cast<size_t>(ascendcPlatform.GetLibApiWorkSpaceSize());
    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = userWorkspaceSize + systemWorkspaceSize;

    return ge::GRAPH_SUCCESS;
}

