#include "kernel_operator.h"

// Specialized for kernel_size=3, stride=2, padding=1, dilation=1 and FP32.
// A complete output-width tile is reduced in parallel with Vector Max.  The
// stride-2 / cross-plane gather is staged explicitly because its GM addresses
// are not representable as one contiguous MTE transfer.
class KernelMaxPooling3dCustom {
public:
    static constexpr uint32_t TILE = 64;
    static constexpr float NEG_MAX = -3.402823466e+38f;

    __aicore__ inline KernelMaxPooling3dCustom() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                               uint32_t n, uint32_t c,
                               uint32_t dIn, uint32_t hIn, uint32_t wIn,
                               uint32_t dOut, uint32_t hOut, uint32_t wOut,
                               uint32_t totalRows, uint32_t blockDim,
                               uint32_t rowsPerBlock)
    {
        n_ = n;
        c_ = c;
        dIn_ = dIn;
        hIn_ = hIn;
        wIn_ = wIn;
        dOut_ = dOut;
        hOut_ = hOut;
        wOut_ = wOut;
        totalRows_ = totalRows;
        blockDim_ = blockDim;
        rowsPerBlock_ = rowsPerBlock;

        hwIn_ = static_cast<uint64_t>(hIn_) * wIn_;
        dhwIn_ = static_cast<uint64_t>(dIn_) * hwIn_;
        hwOut_ = static_cast<uint64_t>(hOut_) * wOut_;
        dhwOut_ = static_cast<uint64_t>(dOut_) * hwOut_;

        xGm_.SetGlobalBuffer((__gm__ float *)x);
        yGm_.SetGlobalBuffer((__gm__ float *)y);
        pipe_.InitBuffer(inputQueue_, 1, TILE * sizeof(float));
        pipe_.InitBuffer(outputQueue_, 1, TILE * sizeof(float));
        pipe_.InitBuffer(maxBuf_, TILE * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        if (wOut_ == 0 || totalRows_ == 0) {
            return;
        }

        const uint32_t blockIdx = static_cast<uint32_t>(AscendC::GetBlockIdx());
        const uint32_t startRow = blockIdx * rowsPerBlock_;
        uint32_t endRow = startRow + rowsPerBlock_;
        if (endRow > totalRows_) {
            endRow = totalRows_;
        }

        auto maxLocal = maxBuf_.Get<float>();
        for (uint32_t row = startRow; row < endRow; ++row) {
            uint32_t index = row;
            const uint32_t oh = index % hOut_;
            index /= hOut_;
            const uint32_t od = index % dOut_;
            index /= dOut_;
            const uint32_t ci = index % c_;
            index /= c_;
            const uint32_t ni = index;

            const uint64_t xNcBase =
                (static_cast<uint64_t>(ni) * c_ + ci) * dhwIn_;
            const uint64_t yRowBase =
                (static_cast<uint64_t>(ni) * c_ + ci) * dhwOut_ +
                (static_cast<uint64_t>(od) * hOut_ + oh) * wOut_;

            for (uint32_t outBase = 0; outBase < wOut_; outBase += TILE) {
                uint32_t validLen = wOut_ - outBase;
                if (validLen > TILE) {
                    validLen = TILE;
                }
                AscendC::Duplicate(maxLocal, NEG_MAX, TILE);

                for (int32_t kd = 0; kd < 3; ++kd) {
                    const int32_t id = static_cast<int32_t>(od) * 2 - 1 + kd;
                    for (int32_t kh = 0; kh < 3; ++kh) {
                        const int32_t ih = static_cast<int32_t>(oh) * 2 - 1 + kh;
                        for (int32_t kw = 0; kw < 3; ++kw) {
                            auto inputLocal = inputQueue_.AllocTensor<float>();
                            for (uint32_t lane = 0; lane < TILE; ++lane) {
                                float value = NEG_MAX;
                                const int32_t iw =
                                    static_cast<int32_t>(outBase + lane) * 2 - 1 + kw;
                                if (lane < validLen && id >= 0 &&
                                    id < static_cast<int32_t>(dIn_) && ih >= 0 &&
                                    ih < static_cast<int32_t>(hIn_) && iw >= 0 &&
                                    iw < static_cast<int32_t>(wIn_)) {
                                    const uint64_t offset = xNcBase +
                                        static_cast<uint64_t>(id) * hwIn_ +
                                        static_cast<uint64_t>(ih) * wIn_ +
                                        static_cast<uint64_t>(iw);
                                    value = xGm_.GetValue(offset);
                                }
                                inputLocal.SetValue(lane, value);
                            }
                            inputQueue_.EnQue(inputLocal);
                            inputLocal = inputQueue_.DeQue<float>();
                            AscendC::Max(maxLocal, maxLocal, inputLocal, TILE);
                            inputQueue_.FreeTensor(inputLocal);
                        }
                    }
                }

                auto outputLocal = outputQueue_.AllocTensor<float>();
                AscendC::DataCopy(outputLocal, maxLocal, TILE);
                outputQueue_.EnQue(outputLocal);
                outputLocal = outputQueue_.DeQue<float>();
                AscendC::DataCopyExtParams outParams(
                    1, validLen * sizeof(float), 0, 0, 0);
                AscendC::DataCopyPad(yGm_[yRowBase + outBase], outputLocal, outParams);
                outputQueue_.FreeTensor(outputLocal);
            }
        }
    }

private:
    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> inputQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outputQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maxBuf_;
    AscendC::GlobalTensor<float> xGm_;
    AscendC::GlobalTensor<float> yGm_;

    uint32_t n_, c_, dIn_, hIn_, wIn_;
    uint32_t dOut_, hOut_, wOut_;
    uint32_t totalRows_, blockDim_, rowsPerBlock_;
    uint64_t hwIn_, dhwIn_, hwOut_, dhwOut_;
};

extern "C" __global__ __aicore__ void max_pooling3d_custom(
    GM_ADDR x, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);
    KernelMaxPooling3dCustom op;
    op.Init(x, y,
            tiling_data.n, tiling_data.c,
            tiling_data.d_in, tiling_data.h_in, tiling_data.w_in,
            tiling_data.d_out, tiling_data.h_out, tiling_data.w_out,
            tiling_data.totalRows, tiling_data.blockDim,
            tiling_data.rowsPerBlock);
    op.Process();
}

