                    float v0 = xGm_.GetValue(base + (uint64_t)(r + 0) * inner);
                    float v1 = xGm_.GetValue(base + (uint64_t)(r + 1) * inner);
                    float v2 = xGm_.GetValue(base + (uint64_t)(r + 2) * inner);
