#include "kernel_operator.h"

// x: [128,4096,4095] FP32, reduce dim=1, y: [128,4095].
// Each block owns whole batch rows, while 1024 adjacent output columns are
// reduced together through the Vector pipeline.
class KernelMaxReductionOverADimensionCustom {
public:
    static constexpr uint32_t TILE = 1024;
    static constexpr float NEG_MAX = -3.402823466e+38f;

    __aicore__ inline KernelMaxReductionOverADimensionCustom() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                               uint32_t totalX, uint32_t totalY,
                               uint32_t batch, uint32_t reduceDim,
                               uint32_t innerDim)
    {
        batch_ = batch;
        reduceDim_ = reduceDim;
        innerDim_ = innerDim;
        xGm_.SetGlobalBuffer((__gm__ float *)x, totalX);
        yGm_.SetGlobalBuffer((__gm__ float *)y, totalY);
        pipe_.InitBuffer(inputQueue_, 1, TILE * sizeof(float));
        pipe_.InitBuffer(outputQueue_, 1, TILE * sizeof(float));
        pipe_.InitBuffer(maxBuf_, TILE * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        if (batch_ == 0 || reduceDim_ == 0 || innerDim_ == 0) {
            return;
        }
        const uint32_t blockNum = static_cast<uint32_t>(AscendC::GetBlockNum());
        const uint32_t blockIdx = static_cast<uint32_t>(AscendC::GetBlockIdx());
        if (blockNum == 0) {
            return;
        }

        auto maxLocal = maxBuf_.Get<float>();
        for (uint32_t b = blockIdx; b < batch_; b += blockNum) {
            const uint64_t xBatchBase =
                static_cast<uint64_t>(b) * reduceDim_ * innerDim_;
            const uint64_t yBatchBase = static_cast<uint64_t>(b) * innerDim_;
            for (uint32_t innerBase = 0; innerBase < innerDim_; innerBase += TILE) {
                uint32_t validLen = innerDim_ - innerBase;
                if (validLen > TILE) {
                    validLen = TILE;
                }
                const uint8_t rightPad = static_cast<uint8_t>(TILE - validLen);
                AscendC::Duplicate(maxLocal, NEG_MAX, TILE);

                for (uint32_t r = 0; r < reduceDim_; ++r) {
                    auto inputLocal = inputQueue_.AllocTensor<float>();
                    const uint64_t offset = xBatchBase +
                        static_cast<uint64_t>(r) * innerDim_ + innerBase;
                    AscendC::DataCopyExtParams inParams(
                        1, static_cast<uint32_t>(validLen * sizeof(float)), 0, 0, 0);
                    AscendC::DataCopyPadExtParams<float> padParams(
                        true, 0, rightPad, NEG_MAX);
                    AscendC::DataCopyPad(inputLocal, xGm_[offset], inParams, padParams);
                    inputQueue_.EnQue(inputLocal);
                    inputLocal = inputQueue_.DeQue<float>();
                    AscendC::Max(maxLocal, maxLocal, inputLocal, TILE);
                    inputQueue_.FreeTensor(inputLocal);
                }

                auto outputLocal = outputQueue_.AllocTensor<float>();
                AscendC::DataCopy(outputLocal, maxLocal, TILE);
                outputQueue_.EnQue(outputLocal);
                outputLocal = outputQueue_.DeQue<float>();
                AscendC::DataCopyExtParams outParams(
                    1, static_cast<uint32_t>(validLen * sizeof(float)), 0, 0, 0);
                AscendC::DataCopyPad(yGm_[yBatchBase + innerBase], outputLocal, outParams);
                outputQueue_.FreeTensor(outputLocal);
            }
        }
    }

private:
    AscendC::TPipe pipe_;
    AscendC::TQue<AscendC::TPosition::VECIN, 1> inputQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 1> outputQueue_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> maxBuf_;
    AscendC::GlobalTensor<float> xGm_;
    AscendC::GlobalTensor<float> yGm_;
    uint32_t batch_{0};
    uint32_t reduceDim_{0};
    uint32_t innerDim_{0};
};

extern "C" __global__ __aicore__ void max_reduction_over_a_dimension_custom(
    GM_ADDR x, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    (void)workspace;
    GET_TILING_DATA(tiling_data, tiling);
    KernelMaxReductionOverADimensionCustom op;
    op.Init(x, y, tiling_data.totalX, tiling_data.totalY,
            tiling_data.batch, tiling_data.reduceDim, tiling_data.innerDim);
    op.Process();
}

